import{c as t,Q as o,j as a,m as n}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"TOTP (authenticator app)","description":"Set up and use Google Authenticator, Authy, or any TOTP-compatible app.","frontmatter":{"title":"TOTP (authenticator app)","description":"Set up and use Google Authenticator, Authy, or any TOTP-compatible app."},"headers":[],"relativePath":"auth/totp.md","filePath":"auth/totp.md"}'),i={name:"auth/totp.md"};function r(s,e,c,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<p>TOTP (Time-based One-Time Password) is a standard (RFC 6238) for generating short-lived codes using a secret key and the current time. Authenticator apps like Google Authenticator, Authy, and 1Password implement this standard.</p><p>When TOTP is enrolled, it replaces email OTP as the second factor. Instead of waiting for an email, the user opens their authenticator app and enters the 6-digit code shown there.</p><h2 id="enrollment" tabindex="-1">Enrollment <a class="header-anchor" href="#enrollment" aria-label="Permalink to &quot;Enrollment&quot;">​</a></h2><ol><li>Go to <code>/profile/totp/enroll</code>.</li><li>Scan the QR code with your authenticator app. If you cannot scan it, expand &quot;Can&#39;t scan?&quot; and enter the key manually.</li><li>Enter the 6-digit code currently shown in your app to confirm that enrollment worked.</li><li>GateKeeper displays 8 one-time recovery codes. Save these somewhere safe - a password manager is ideal. They are not shown again.</li></ol><p>GateKeeper does not store the TOTP secret until you confirm enrollment with a valid code. This prevents half-finished enrollments from locking you out.</p><h2 id="logging-in-with-totp" tabindex="-1">Logging in with TOTP <a class="header-anchor" href="#logging-in-with-totp" aria-label="Permalink to &quot;Logging in with TOTP&quot;">​</a></h2><p>After your password is verified, GateKeeper redirects you to <code>/login/totp</code> instead of the email OTP page. Enter the 6-digit code from your authenticator app.</p><p>GateKeeper accepts codes from the current 30-second window and the previous one. This handles small clock differences between your device and the server (known as &quot;clock skew&quot;).</p><p>After 5 failed attempts within 10 minutes, the account is locked for 10 minutes.</p><h2 id="recovery-codes" tabindex="-1">Recovery codes <a class="header-anchor" href="#recovery-codes" aria-label="Permalink to &quot;Recovery codes&quot;">​</a></h2><p>If you lose access to your authenticator app, use one of your recovery codes at <code>/login/totp/recovery</code>. Each code works once and is permanently invalidated after use.</p><p>The admin can see how many recovery codes you have left at <code>/admin/users/:id</code>. They cannot see the codes themselves.</p><h2 id="disabling-totp" tabindex="-1">Disabling TOTP <a class="header-anchor" href="#disabling-totp" aria-label="Permalink to &quot;Disabling TOTP&quot;">​</a></h2><p>Go to <code>/profile/totp/disable</code> and enter a valid code from your authenticator app. This confirms it is you and not someone who just has your session cookie.</p><p>Admins can also disable TOTP for any user from the admin panel, without needing the authenticator code.</p>',15)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
